import 'package:core/core/constants/muscle_taxonomy_v1.dart';
import 'package:core/domain/models/exercise.dart';

/// UI browsing facets only; they do not affect recorded set attribution.
enum ExerciseMovementCategory {
  horizontalPush,
  verticalPull,
  horizontalPull,
  shoulder,
  arms,
  squatLunge,
  kneeFlexion,
  hipHinge,
  hipControl,
  ankle,
  core,
  scapular,
  gripCarry,
}

extension ExerciseMovementCategoryLabel on ExerciseMovementCategory {
  String get labelEs => switch (this) {
    ExerciseMovementCategory.horizontalPush => 'Empuje horizontal',
    ExerciseMovementCategory.verticalPull => 'Tracción vertical',
    ExerciseMovementCategory.horizontalPull => 'Remo / tracción horizontal',
    ExerciseMovementCategory.shoulder => 'Trabajo de hombro',
    ExerciseMovementCategory.arms => 'Flexión / extensión de codo',
    ExerciseMovementCategory.squatLunge => 'Sentadillas / zancadas',
    ExerciseMovementCategory.kneeFlexion => 'Flexión de rodilla',
    ExerciseMovementCategory.hipHinge => 'Bisagra de cadera',
    ExerciseMovementCategory.hipControl => 'Cadera / glúteos / aductores',
    ExerciseMovementCategory.ankle => 'Tobillo / pantorrilla',
    ExerciseMovementCategory.core => 'Abdomen / antirotación',
    ExerciseMovementCategory.scapular => 'Control de escápulas',
    ExerciseMovementCategory.gripCarry => 'Antebrazo / agarre',
  };
}

/// Compound = multiple-joint; isolation = targeted single movement;
/// stability = primarily resist/control motion. Informational, not clinical.
enum ExerciseMechanics { compound, isolation, stability }

extension ExerciseMechanicsLabel on ExerciseMechanics {
  String get labelEs => switch (this) {
    ExerciseMechanics.compound => 'Compuesto',
    ExerciseMechanics.isolation => 'Aislado',
    ExerciseMechanics.stability => 'Estabilidad / control',
  };
}

/// Metadata only; the stored Exercise/Hive schema and old IDs remain unchanged.
/// A portion is a regional *emphasis*, not an independently counted set.
class PresetAnatomyProfile {
  final String primaryId;
  final List<String> secondaryIds;
  final List<String> emphasisIds;
  final bool reviewed;

  const PresetAnatomyProfile({
    required this.primaryId,
    this.secondaryIds = const <String>[],
    this.emphasisIds = const <String>[],
    this.reviewed = false,
  });
}

class ExerciseDefinitionV2 {
  final String id;
  final String name;
  final String equipment;
  final String movementPattern;
  final ExerciseMovementCategory movementCategory;
  final ExerciseMechanics mechanics;
  final String difficulty;
  final bool unilateral;
  final String technique;
  final String commonMistake;
  final List<String> aliases;
  final PresetAnatomyProfile anatomy;

  const ExerciseDefinitionV2({
    required this.id,
    required this.name,
    required this.equipment,
    required this.movementPattern,
    required this.movementCategory,
    required this.mechanics,
    required this.difficulty,
    required this.unilateral,
    required this.technique,
    required this.commonMistake,
    required this.anatomy,
    this.aliases = const <String>[],
  });

  Exercise toExercise() => Exercise(
        id: id,
        name: name,
        muscleGroup: MuscleTaxonomyV1.byId[anatomy.primaryId]!.labelEs,
        secondaryMuscles: [
          for (final nodeId in anatomy.secondaryIds)
            MuscleTaxonomyV1.byId[nodeId]!.labelEs,
        ],
        equipment: equipment,
        instructions: '$technique. Evita $commonMistake.',
      );
}

